From 9e9d7b028ade49c6fdd4580ced5b30efe76b2d70 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:33:54 +0100
Subject: [PATCH] globalaccel: don't allow media shortcuts when media controls
 are hidden

The media keys always reached the player while the screen was locked,
even when the lock screen was set not to show media controls. Now the
media control shortcuts are only allowed when that setting is enabled.

BUG: 461891
---
 globalaccel.cpp | 9 ++++++++-
 1 file changed, 8 insertions(+), 1 deletion(-)

diff --git a/globalaccel.cpp b/globalaccel.cpp
index 2eb05ac9..97fe9eea 100644
--- a/globalaccel.cpp
+++ b/globalaccel.cpp
@@ -5,6 +5,8 @@ SPDX-License-Identifier: GPL-2.0-or-later
 */
 #include "globalaccel.h"

+#include <KConfig>
+#include <KConfigGroup>
 #include <KKeyServer>
 #include <netwm.h>

@@ -72,6 +74,11 @@ void GlobalAccel::components(QDBusPendingCallWatcher *self)
         m_updatingInformation--;
         return;
     }
+    const bool showMediaControls = KConfig(QStringLiteral("kscreenlockerrc"))
+                                       .group(QStringLiteral("Greeter"))
+                                       .group(QStringLiteral("LnF"))
+                                       .group(QStringLiteral("General"))
+                                       .readEntry("showMediaControls", true);
     // go through all components, check whether they are in our whitelist
     // if they are whitelisted we check whether they are active
     for (const auto &path : reply.value()) {
@@ -83,7 +90,7 @@ void GlobalAccel::components(QDBusPendingCallWatcher *self)
                 break;
             }
         }
-        if (!whitelisted) {
+        if (!whitelisted || (!showMediaControls && objectPath == QLatin1String("/component/mediacontrol"))) {
             continue;
         }
         auto message = QDBusMessage::createMethodCall(s_kglobalAccelService, objectPath, s_componentInterface, QStringLiteral("isActive"));
-- 
